    private const string Lessons="/api/v1/evaluations/lessons";
    private async Task<(Guid Level,Guid Session,Guid Coach)> LessonFixture(FoundationDbContext db,TrainingGroup? selected=null)
    {
        var source=selected??await db.TrainingGroups.FirstAsync(g=>g.AcademyId==DemoSeed.NogoomAcademyId&&g.IsActive);var level=Guid.NewGuid();var group=Guid.NewGuid();var session=Guid.NewGuid();var owner=await db.Users.Where(u=>u.Email==DemoSeed.OwnerEmail).Select(u=>u.Id).SingleAsync();var coach=await db.AcademyMemberships.Where(m=>m.AcademyId==source.AcademyId&&m.Role==AcademyRole.Coach&&m.IsActive).Select(m=>m.Id).FirstAsync();
        db.TrainingLevels.Add(new(){Id=level,AcademyId=source.AcademyId,SportId=source.SportId,ArabicName="مستوى خطة حصة اصطناعي "+level.ToString("N")[..8],Rank=90});
        db.TrainingGroups.Add(new(){Id=group,AcademyId=source.AcademyId,BranchId=source.BranchId,SportId=source.SportId,AgeCategoryId=source.AgeCategoryId,TrainingLevelId=level,ArabicName="مجموعة خطة حصة اصطناعية "+group.ToString("N")[..8]});
        db.StaffGroupAssignments.Add(new(){Id=Guid.NewGuid(),AcademyId=source.AcademyId,TrainingGroupId=group,AcademyMembershipId=coach});
        db.TrainingSessions.Add(new(){Id=session,AcademyId=source.AcademyId,TrainingGroupId=group,BranchId=source.BranchId,SportId=source.SportId,AgeCategoryId=source.AgeCategoryId,SessionDate=DateOnly.FromDateTime(DateTime.UtcNow).AddDays(2),StartTime=new(14,0),EndTime=new(15,0),CreatedByUserId=owner,Source=TrainingSessionSource.Manual});await db.SaveChangesAsync();return(level,session,coach);
    }
    private static async Task<Guid> LessonId(HttpResponseMessage r){r.EnsureSuccessStatusCode();return(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();}
    private static ExerciseWrite ExerciseBody(Guid level)=>new(level,"تمرين اصطناعي أصلي","تمرير","نص اختبار اصطناعي وليس تعليمات سلامة مائية","كرة وأقماع؛ قيود يراجعها المختص",10,"Original","مؤلف محتوى الاختبار الاصطناعي",Guid.NewGuid());
    [Fact] public async Task Lesson_duration_review_session_assignment_replay_history_and_role_isolation_use_real_saved_sources()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var f=await LessonFixture(db);var attendance=await db.PlayerAttendances.CountAsync();var collections=await db.Collections.CountAsync();var notices=await db.AcademyNotices.CountAsync();
        var body=ExerciseBody(f.Level);var ex=await LessonId(await Send(owner,Lessons+"/exercises",body));Assert.Equal(ex,await LessonId(await Send(owner,Lessons+"/exercises",body)));Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,Lessons+"/exercises",body with{Title="تغيير نفس المفتاح"})).StatusCode);
        Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,Lessons+"/exercises",body with{RequestId=Guid.NewGuid()})).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await family.GetAsync(Lessons+"/library")).StatusCode);Assert.DoesNotContain(ex.ToString(),await coach.GetStringAsync(Lessons+"/library"));
        var r=new LessonTemplateWrite(f.Level,"خطة حساب المدد الاصطناعية",76,new[]{new LessonStepWrite(ex,10),new(ex,15),new(ex,20),new(ex,10),new(ex,5)},Guid.NewGuid());var wrong=await LessonId(await Send(owner,Lessons+"/templates",r));var detail=await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{wrong}");Assert.Equal(60,detail.GetProperty("computedMinutes").GetInt32());Assert.False(detail.GetProperty("durationMatches").GetBoolean());
        Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/templates/{wrong}/review",new LessonReview(detail.GetProperty("item").GetProperty("version").GetUInt32(),true,Guid.NewGuid()))).StatusCode);
        var corrected=await LessonId(await Send(owner,Lessons+"/templates",r with{DeclaredMinutes=60,RequestId=Guid.NewGuid(),CopiedFromId=wrong}));var plan=await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{corrected}");var version=plan.GetProperty("item").GetProperty("version").GetUInt32();
        Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/templates/{corrected}/review",new LessonReview(version,true,Guid.NewGuid()))).StatusCode);
        db.ChangeTracker.Clear();var ev=await db.TrainingExercises.AsNoTracking().Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev+1,true,Guid.NewGuid()))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,false,Guid.NewGuid()))).StatusCode);Assert.Equal(HttpStatusCode.OK,(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,true,Guid.NewGuid()))).StatusCode);
        Assert.Equal(HttpStatusCode.OK,(await Send(owner,$"{Lessons}/templates/{corrected}/review",new LessonReview(version,true,Guid.NewGuid()))).StatusCode);
        var assign=new LessonAssign(corrected,0,Guid.NewGuid());var assignment=await LessonId(await Send(coach,$"{Lessons}/sessions/{f.Session}",assign));Assert.Equal(assignment,await LessonId(await Send(coach,$"{Lessons}/sessions/{f.Session}",assign)));Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,$"{Lessons}/sessions/{f.Session}",assign with{PreviousRevision=9})).StatusCode);
        var reread=await coach.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}");Assert.Equal(60,reread.GetProperty("active").GetProperty("computedMinutes").GetInt32());Assert.Equal(1,reread.GetProperty("revision").GetInt32());Assert.Equal(1,reread.GetProperty("history").GetArrayLength());
        Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync($"{Lessons}/sessions/{f.Session}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync($"{Lessons}/templates/{corrected}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await family.GetAsync($"{Lessons}/sessions/{f.Session}")).StatusCode);
        Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(corrected,0,Guid.NewGuid()))).StatusCode);
        var other=await LessonId(await Send(owner,Lessons+"/templates",r with{Title="خطة بديلة محفوظة",DeclaredMinutes=60,RequestId=Guid.NewGuid(),CopiedFromId=corrected}));var otherData=await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{other}");Assert.Equal(HttpStatusCode.OK,(await Send(owner,$"{Lessons}/templates/{other}/review",new LessonReview(otherData.GetProperty("item").GetProperty("version").GetUInt32(),true,Guid.NewGuid()))).StatusCode);await LessonId(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(other,1,Guid.NewGuid())));Assert.Equal(assignment,await LessonId(await Send(coach,$"{Lessons}/sessions/{f.Session}",assign)));reread=await coach.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}");Assert.Equal(2,reread.GetProperty("revision").GetInt32());Assert.Equal(other,reread.GetProperty("active").GetProperty("item").GetProperty("id").GetGuid());
        var groupId=awaitGroup(db,f.Session);var a=await db.StaffGroupAssignments.SingleAsync(a=>a.TrainingGroupId==groupId&&a.AcademyMembershipId==f.Coach);a.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync($"{Lessons}/sessions/{f.Session}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(coach,$"{Lessons}/sessions/{f.Session}",assign)).StatusCode);
        var exRow=await db.TrainingExercises.SingleAsync(e=>e.Id==ex);exRow.Title="محاولة كتابة فوق الأصل";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());db.ChangeTracker.Clear();
        var sql=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"TrainingExercises\" SET \"Title\"='overwrite' WHERE \"Id\"={ex}"));Assert.Equal("23514",sql.SqlState);
        Assert.Equal(attendance,await db.PlayerAttendances.CountAsync());Assert.Equal(collections,await db.Collections.CountAsync());Assert.Equal(notices,await db.AcademyNotices.CountAsync());
    }
    private static Guid awaitGroup(FoundationDbContext db,Guid session)=>db.TrainingSessions.Where(s=>s.Id==session).Select(s=>s.TrainingGroupId).Single();
    [Fact] public async Task Lesson_branch_delegate_cannot_change_shared_library_and_live_edit_revocation_precedes_assignment_replay()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
        var grant=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="evaluations");var before=grant==null?null:JsonSerializer.Serialize(grant);var added=grant==null;grant??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="evaluations"};
        try{
            grant.IsActive=true;grant.Read=true;grant.Add=true;grant.Edit=true;grant.Delete=false;if(added)db.StaffActionGrants.Add(grant);await db.SaveChangesAsync();var f=await LessonFixture(db,group);var ex=await LessonId(await Send(owner,Lessons+"/exercises",ExerciseBody(f.Level)));var ev=await db.TrainingExercises.Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,true,Guid.NewGuid()))).EnsureSuccessStatusCode();
            var plan=await LessonId(await Send(owner,Lessons+"/templates",new LessonTemplateWrite(f.Level,"خطة تفويض فرع اصطناعية",60,[new(ex,60)],Guid.NewGuid())));var v=(await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{plan}")).GetProperty("item").GetProperty("version").GetUInt32();(await Send(owner,$"{Lessons}/templates/{plan}/review",new LessonReview(v,true,Guid.NewGuid()))).EnsureSuccessStatusCode();
            Assert.False((await admin.GetFromJsonAsync<JsonElement>(Lessons+"/library")).GetProperty("canCreate").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,Lessons+"/exercises",ExerciseBody(f.Level))).StatusCode);
            var body=new LessonAssign(plan,0,Guid.NewGuid());await LessonId(await Send(admin,$"{Lessons}/sessions/{f.Session}",body));grant.Edit=false;await db.SaveChangesAsync();Assert.False((await admin.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}")).GetProperty("canAssign").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Lessons}/sessions/{f.Session}",body)).StatusCode);
            var branch=await db.MembershipBranchAccesses.SingleAsync(b=>b.MembershipId==member&&b.BranchId==group.BranchId);branch.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"{Lessons}/sessions/{f.Session}")).StatusCode);Assert.Equal(1,await db.SessionLessonAssignments.CountAsync(a=>a.TrainingSessionId==f.Session));
        }finally{if(added)db.StaffActionGrants.Remove(grant);else db.Entry(grant).CurrentValues.SetValues(JsonSerializer.Deserialize<Academy.Infrastructure.Tenancy.StaffActionGrant>(before!)!);await db.SaveChangesAsync();}
    });
    [Fact] public async Task Lesson_template_rejects_foreign_level_and_inactive_or_wrong_duration_session_without_changing_attendance()
    {
        using var owner=await Staff();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var f=await LessonFixture(db);var ex=await LessonId(await Send(owner,Lessons+"/exercises",ExerciseBody(f.Level)));var second=await LessonFixture(db);
        Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,Lessons+"/templates",new LessonTemplateWrite(second.Level,"غير مطابق",60,[new(ex,60)],Guid.NewGuid()))).StatusCode);
        Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,Lessons+"/templates",new{trainingLevelId=f.Level,title="قائمة تالفة",declaredMinutes=60,steps=new object?[]{null},requestId=Guid.NewGuid()})).StatusCode);
        Assert.Equal(HttpStatusCode.NotFound,(await Send(owner,Lessons+"/exercises",ExerciseBody(Guid.NewGuid()))).StatusCode);
        var ev=await db.TrainingExercises.Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,true,Guid.NewGuid()))).EnsureSuccessStatusCode();
        var plan=await LessonId(await Send(owner,Lessons+"/templates",new LessonTemplateWrite(f.Level,"خطة مطابقة للحصة",60,[new(ex,60)],Guid.NewGuid())));var version=(await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{plan}")).GetProperty("item").GetProperty("version").GetUInt32();(await Send(owner,$"{Lessons}/templates/{plan}/review",new LessonReview(version,true,Guid.NewGuid()))).EnsureSuccessStatusCode();
        var session=await db.TrainingSessions.SingleAsync(s=>s.Id==f.Session);session.EndTime=new(14,45);await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(plan,0,Guid.NewGuid()))).StatusCode);
        session.EndTime=new(15,0);session.Status=TrainingSessionStatus.Held;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(plan,0,Guid.NewGuid()))).StatusCode);
        session.Status=TrainingSessionStatus.Scheduled;var level=await db.TrainingLevels.SingleAsync(l=>l.Id==f.Level);level.IsActive=false;await db.SaveChangesAsync();Assert.False((await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}")).GetProperty("canAssign").GetBoolean());Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(plan,0,Guid.NewGuid()))).StatusCode);Assert.False(await db.SessionLessonAssignments.AnyAsync(a=>a.TrainingSessionId==f.Session));
    }
}
